  ('g2-s3-ratio_scaling-difficult-0007', 2, 3, 'ratio_scaling', 'difficult', '{"r1": 2, "r2": 7, "mult": 4}'::jsonb, 'Two numbers are in the ratio 2:7. The bigger number is 20 more than the smaller. What is the bigger number?', '["33", "8", "28", "20"]'::jsonb, '28', '["gave the smaller number instead of the bigger", "gave the difference itself instead of the bigger number", "off by one ratio-unit''s worth"]'::jsonb, 'The difference 20 corresponds to 5 ratio units, so 1 unit = 4. Bigger = 7 x 4 = 28.', NULL, '', 60, NULL, 'template-mtap-g2-v1', true),
